from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def createTree(parent, N):
    if N == 0:
        return None

    # Create a list to store nodes
    nodes = [TreeNode(i) for i in range(N)]

    # Initialize root
    root = None

    # Create tree from parent array
    for i in range(N):
        if parent[i] == -1:
            root = nodes[i]
        else:
            p = parent[i]
            if nodes[p].left is None:
                nodes[p].left = nodes[i]
            else:
                nodes[p].right = nodes[i]

    return root

# Example usage:
# N = 7
# parent = [-1, 0, 0, 1, 1, 3, 5]
# root = createTree(parent, N)
# This will construct the tree and return the root node.
